import{_ as n,o as t,c as r,a4 as o}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0040 — Échangeur OIDC des usagers livré inactif : FranceConnect sans code chez l'exploitant","description":"Extrait de docs/adr/0040-echangeur-oidc-des-usagers-livre-inactif.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0040 — Échangeur OIDC des usagers livré inactif : FranceConnect sans code chez l'exploitant","description":"Extrait de docs/adr/0040-echangeur-oidc-des-usagers-livre-inactif.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0040-echangeur-oidc-des-usagers-livre-inactif.md","filePath":"developpeurs/adr/0040-echangeur-oidc-des-usagers-livre-inactif.md"}`),a={name:"developpeurs/adr/0040-echangeur-oidc-des-usagers-livre-inactif.md"};function c(s,e,i,d,u,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0040--échangeur-oidc-des-usagers-livré-inactif--franceconnect-sans-code-chez-lexploitant" tabindex="-1">ADR-0040 — Échangeur OIDC des usagers livré inactif : FranceConnect sans code chez l&#39;exploitant <a class="header-anchor" href="#adr-0040--échangeur-oidc-des-usagers-livré-inactif--franceconnect-sans-code-chez-lexploitant" aria-label="Permalink to &quot;ADR-0040 — Échangeur OIDC des usagers livré inactif : FranceConnect sans code chez l&#39;exploitant {#adr-0040--échangeur-oidc-des-usagers-livré-inactif--franceconnect-sans-code-chez-lexploitant}&quot;">​</a></h1><p><strong>Date :</strong> 23 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit du 10 septembre 2026, constat P1 n°5 (« FranceConnect répond 503 : l&#39;échangeur OIDC n&#39;est pas branché ») ; CDC_CMS_AI_Native_v1.1 §8.1 (compte usager, OIDC type FranceConnect), §14.11 (le Core démarre sans configuration) ; applique le patron de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a> et celui de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0029-sorties-reseau-du-socle-ia">ADR-0029</a> ; suit le parti de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0016-synonymes-stopwords-reecriture-de-requete">ADR-0016</a> (charger à chaque usage, pas de cache sans mesure) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0039-journalisation-applicative">ADR-0039</a> (journal) ; annote l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0017-fichiers-personnels-adresses-par-identifiant">ADR-0017</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;Epic E12 a livré le flux OIDC des usagers presque entier : <code>state</code>, <code>nonce</code>, PKCE, usage unique de la redirection, les cinq contrôles du jeton d&#39;identité (<code>iss</code>, <code>aud</code>, <code>exp</code>, <code>nonce</code>, <code>sub</code>), la liaison de compte et le régime de rétention de l&#39;identité pivot (<code>app/end_users/oidc.py</code>). Il manquait l&#39;appel réseau : échanger le code d&#39;autorisation contre un jeton, et vérifier la signature de ce jeton. Le Core déclarait pour cela un point d&#39;extension, <code>register_oidc_exchanger()</code>, et laissait l&#39;implémentation « au déploiement ».</p><p>L&#39;argument de l&#39;époque tenait en une phrase de la docstring d&#39;<code>oidc.py</code> : le captcha et le courriel se branchent avec une clé, l&#39;échangeur OIDC demande un client HTTP, un JWKS, une rotation de clés et un secret client, donc de l&#39;infrastructure. L&#39;ADR-0027 a montré ce que coûte cet argument dans les faits : un exploitant de collectivité n&#39;écrit pas de Python, et un point d&#39;extension vide est une fonction absente. Concrètement, sur toute installation livrée, le bouton FranceConnect conduisait à un 503 — et l&#39;audit du 10 septembre l&#39;a classé parmi les sept bloquants avant mise en service.</p><p>Deux difficultés propres à ce chantier, que les adaptateurs de l&#39;ADR-0027 n&#39;avaient pas :</p><ul><li><strong>Un secret par organisation.</strong> Chaque collectivité a son propre <code>client_id</code> chez FranceConnect, donc son propre secret. Le secret ne peut pas être un réglage d&#39;instance unique ; il ne peut pas non plus être rangé dans <code>organizations.settings</code>, que l&#39;API rend à l&#39;écran d&#39;un administrateur.</li><li><strong>Un secret qui part vers une adresse déclarée par un administrateur d&#39;organisation.</strong> C&#39;est exactement la forme du constat critique n°1.1 de l&#39;audit du 15 septembre, fermé pour le socle IA par l&#39;ADR-0029 : sans borne, un administrateur déclare un point d&#39;échange à lui, nomme <code>DATABASE_URL</code> comme variable du secret, et se fait livrer le mot de passe de la base.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le Core livre un échangeur OIDC standard, inactif tant que l&#39;instance ne déclare pas les hôtes de ses fournisseurs d&#39;identité.</strong> Ce qui est livré est un code capable d&#39;appeler, jamais un appel.</p><h3 id="1-un-module-une-frontière-vérifiée" tabindex="-1">1. Un module, une frontière vérifiée <a class="header-anchor" href="#1-un-module-une-frontière-vérifiée" aria-label="Permalink to &quot;1. Un module, une frontière vérifiée {#1-un-module-une-frontière-vérifiée}&quot;">​</a></h3><p><code>app/end_users/oidc_exchanger.py</code> — <code>StandardOidcExchanger</code> — est <strong>le seul module de <code>app/end_users</code> qui importe <code>httpx</code></strong>. Un test structurel le vérifie (<code>test_l_echangeur_est_le_seul_module_usager_qui_contacte_le_reseau</code>) : aucun autre fichier du paquet n&#39;importe <code>httpx</code>, <code>requests</code>, <code>aiohttp</code>, <code>urllib3</code>, <code>smtplib</code> ni <code>urllib</code>, à l&#39;exception nommée de <code>urllib.parse</code>, qu&#39;<code>oidc.py</code> emploie depuis E12 pour construire l&#39;URL d&#39;autorisation et qui n&#39;ouvre aucun socket. Le reste du paquet décide (quel compte, quelles revendications, quelle rétention), l&#39;échangeur appelle.</p><h3 id="2-patron-de-ladr-0029--le-secret-par-son-nom-les-hôtes-déclarés" tabindex="-1">2. Patron de l&#39;ADR-0029 : le secret par son nom, les hôtes déclarés <a class="header-anchor" href="#2-patron-de-ladr-0029--le-secret-par-son-nom-les-hôtes-déclarés" aria-label="Permalink to &quot;2. Patron de l&#39;ADR-0029 : le secret par son nom, les hôtes déclarés {#2-patron-de-ladr-0029--le-secret-par-son-nom-les-hôtes-déclarés}&quot;">​</a></h3><ul><li><strong><code>OidcClientSettings.client_secret_env</code></strong> porte le <strong>nom</strong> de la variable d&#39;environnement qui contient le secret, jamais sa valeur. Grammaire <code>^OIDC_[A-Z0-9_]+$</code>, contrôlée <strong>à l&#39;écriture</strong> (sous-classes <code>OidcClientSettingsWrite</code> / <code>EndUserPolicyWrite</code>, utilisées par <code>EndUserPolicyUpdate</code> : 422 dont le chemin est <code>policy.oidc_clients.N.client_secret_env</code>) <strong>et à l&#39;usage</strong> (l&#39;échangeur re-vérifie avant de lire l&#39;environnement). Le modèle de relecture ne porte volontairement aucune grammaire : une valeur hors grammaire écrite directement en base ne met pas la politique entière en 500, elle est refusée là où elle servirait. Même raisonnement que l&#39;ADR-0029 contre le précédent <code>005bfe7</code> : ici, la ligne déjà en base est précisément ce dont il faut cesser de se servir.</li><li><strong><code>OIDC_ALLOWED_ISSUER_HOSTS</code></strong>, réglage d&#39;instance (<code>app/core/config.py</code>, <code>apps/api/.env.example</code>) : vide, aucun échangeur n&#39;est branché et le rappel répond 503 comme avant ; renseigné, l&#39;échangeur standard est branché ; <strong>illisible, le démarrage de l&#39;API et de l&#39;ordonnanceur est refusé</strong> (<code>OidcConfigError</code>). Même grammaire que <code>AI_ALLOWED_ENDPOINT_HOSTS</code>, désormais commune (<code>app/core/outbound_hosts.py</code>, <code>parse_host_list(brut, strict=...)</code>) ; le socle IA la lit en mode non strict pour ne rien changer à son comportement, l&#39;OIDC en mode strict parce que cette liste décide où part un secret.</li><li><strong>Toute adresse contactée</strong> — découverte, point d&#39;échange, JWKS, userinfo — doit être en <code>https</code>, sans identifiant dans l&#39;URL, sur un hôte déclaré. Le secret et les deux adresses de la politique (émetteur, point d&#39;échange) sont vérifiés <strong>avant le premier octet émis</strong> : le secret ne part jamais vers un hôte non déclaré.</li></ul><h3 id="3-branchement--un-échangeur-par-défaut-supplanté-par-un-échangeur-spécifique" tabindex="-1">3. Branchement : un échangeur par défaut, supplanté par un échangeur spécifique <a class="header-anchor" href="#3-branchement--un-échangeur-par-défaut-supplanté-par-un-échangeur-spécifique" aria-label="Permalink to &quot;3. Branchement : un échangeur par défaut, supplanté par un échangeur spécifique {#3-branchement--un-échangeur-par-défaut-supplanté-par-un-échangeur-spécifique}&quot;">​</a></h3><p><code>OidcExchangerRegistry</code> gagne un second étage : un échangeur <strong>par défaut</strong> (<code>set_default</code>), qui sert toute clé de fournisseur sans échangeur spécifique. <code>compose()</code> y pose l&#39;échangeur standard — ou <code>None</code>, pour qu&#39;un second appel ne laisse pas en place un échangeur que les réglages ne décrivent plus — et ne touche jamais aux échangeurs spécifiques : un plugin qui enregistre le sien par <code>register_oidc_exchanger</code> le supplante pour sa clé. <code>GET /account/providers</code> en tire <code>configured</code> sans modification de logique, puisque <code>get()</code> rend désormais l&#39;échangeur par défaut. La ligne <code>demarrage</code> (ADR-0039) porte <code>oidc_echangeur_par_defaut</code> (booléen) à côté de <code>oidc_echangeurs</code> (nombre d&#39;échangeurs spécifiques), jamais un hôte.</p><h3 id="4-protocole" tabindex="-1">4. Protocole <a class="header-anchor" href="#4-protocole" aria-label="Permalink to &quot;4. Protocole {#4-protocole}&quot;">​</a></h3><ul><li><strong>Découverte</strong> <code>{issuer}/.well-known/openid-configuration</code> à chaque échange : l&#39;<code>issuer</code> rendu doit être identique <strong>à l&#39;octet près</strong> à celui de la politique, le <code>token_endpoint</code> identique à celui de la politique. Une découverte ne remplace jamais ce que l&#39;organisation a déclaré, elle le confirme.</li><li><strong>Authentification du client</strong> : <code>client_secret_post</code> si la découverte l&#39;annonce, sinon <code>client_secret_basic</code> — défaut de la spécification quand rien n&#39;est annoncé.</li><li><strong>Signature</strong> : RS256 ou ES256 uniquement ; <code>none</code> et HS* sont refusés, ce qui écarte aussi FranceConnect v1 (HS256). Clé choisie par <code>kid</code> dans le JWKS ; sans <code>kid</code>, le JWKS doit en publier exactement une pour l&#39;algorithme. <code>PyJWT[crypto]</code> vérifie la signature ; <code>PyJWKClient</code> n&#39;est <strong>pas</strong> utilisé (synchrone, <code>urllib</code>) : le JWKS est récupéré par <code>httpx</code>, dans les bornes ci-dessous, puis lu par <code>PyJWK</code>.</li><li><strong>userinfo</strong> (s&#39;il est annoncé) en JSON ou en JWT signé (mêmes règles), avec un <code>sub</code> identique à celui du jeton d&#39;identité ; ses revendications complètent celles du jeton <strong>sans écraser</strong> <code>iss</code>, <code>aud</code>, <code>exp</code>, <code>iat</code>, <code>nbf</code>, <code>nonce</code>, <code>sub</code>, <code>acr</code>, <code>amr</code>, <code>auth_time</code>, <code>azp</code>. Sans <code>userinfo_endpoint</code>, seules restent les revendications du jeton.</li><li><strong>Le Core revérifie ensuite</strong> <code>iss</code>, <code>aud</code>, <code>exp</code>, <code>nonce</code> et <code>sub</code> (<code>validate_id_token_claims</code>, inchangé) : l&#39;échangeur rend <code>OidcTokens(claims=..., id_token_verified=True)</code>, et deux contrôles valent mieux qu&#39;une confiance.</li><li><strong>Pas de cache</strong>, même parti que l&#39;ADR-0016 pour le vocabulaire de recherche (charger à chaque usage tant qu&#39;aucune mesure n&#39;exige un cache) : découverte et JWKS sont récupérés à chaque échange.</li></ul><h3 id="5-bornes-réseau-et-réponses" tabindex="-1">5. Bornes réseau et réponses <a class="header-anchor" href="#5-bornes-réseau-et-réponses" aria-label="Permalink to &quot;5. Bornes réseau et réponses {#5-bornes-réseau-et-réponses}&quot;">​</a></h3><p>Délai de 10 s par appel (délais <code>httpx</code> et borne <code>asyncio.timeout</code> sur l&#39;appel entier) ; <strong>aucune redirection suivie</strong> ; réponse bornée à 1 Mio — <code>Content-Length</code> refusé d&#39;emblée s&#39;il dépasse, puis lecture en flux coupée au premier octet de trop. C&#39;est le premier module du dépôt qui borne ainsi une réponse.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Exception</th><th>Statut du rappel</th></tr></thead><tbody><tr><td>Aucun échangeur, secret absent, nom de variable hors grammaire, hôte non déclaré, <code>http://</code>, identifiants dans l&#39;URL</td><td><code>OidcNotConfigured</code></td><td>503</td></tr><tr><td>Fournisseur injoignable : réseau, délai, 5xx</td><td><code>OidcProviderUnavailable</code> (nouvelle)</td><td>503, et ligne <code>oidc_injoignable</code></td></tr><tr><td>4xx du fournisseur, redirection, réponse trop grosse ou illisible, signature invalide, algorithme refusé, <code>kid</code> inconnu, désaccord de découverte, <code>sub</code> userinfo différent</td><td><code>OidcError</code></td><td>400</td></tr></tbody></table><p>La configuration incomplète est un <strong>503</strong> et non un 400 : l&#39;usager n&#39;y peut rien, un nouvel essai échouera pareil, c&#39;est à l&#39;exploitant d&#39;agir. Les messages de ces refus partent dans la réponse d&#39;une route publique : ils ne nomment pas la variable d&#39;environnement et ne recopient aucun corps de réponse du fournisseur.</p><p>La ligne <code>oidc_injoignable</code> (logger <code>teuthis.oidc</code>, WARNING, patron de l&#39;ADR-0039) porte la clé du fournisseur, l&#39;étape (<code>decouverte</code>, <code>jeton</code>, <code>jwks</code>, <code>userinfo</code>) et la nature de l&#39;échec — <strong>aucune donnée</strong> : ni code d&#39;autorisation, ni jeton, ni secret, ni <code>sub</code>, ni adresse.</p><h3 id="6-écran" tabindex="-1">6. Écran <a class="header-anchor" href="#6-écran" aria-label="Permalink to &quot;6. Écran {#6-écran}&quot;">​</a></h3><p>Extranet › Politique gagne le champ « Variable du secret client » (<code>apps/admin/pages/extranet/politique.vue</code>, <code>apps/admin/types/api.ts</code>), avec une aide liée par <code>aria-describedby</code> qui dit que c&#39;est le <strong>nom</strong> d&#39;une variable d&#39;environnement de l&#39;instance, pas le secret. L&#39;erreur de grammaire du serveur s&#39;affiche sous le champ.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Garder le point d&#39;extension vide</strong></td><td>État antérieur : un 503 permanent sur toute installation dont l&#39;exploitant n&#39;écrit pas de Python. C&#39;est l&#39;argument que l&#39;ADR-0027 a déjà tranché pour le captcha et le courriel.</td></tr><tr><td><strong>Stocker le secret dans <code>organizations.settings</code></strong></td><td>Le secret serait rendu à l&#39;écran de politique, recopié dans chaque sauvegarde et chaque export de la base, et lisible par tout porteur de <code>end_user.manage</code>. Le nom d&#39;une variable ne vaut rien sans l&#39;accès à l&#39;environnement du serveur.</td></tr><tr><td><strong>Un réglage d&#39;instance unique pour le secret</strong></td><td>Faux pour ce produit : chaque collectivité hébergée sur une instance mutualisée a son propre <code>client_id</code>, donc son propre secret.</td></tr><tr><td><strong>Nom de variable libre, borné seulement par la liste d&#39;hôtes</strong></td><td>Deux problèmes distincts, comme dans l&#39;ADR-0029 : la liste d&#39;hôtes empêche d&#39;envoyer le secret ailleurs, la grammaire empêche de désigner un autre secret. Un fournisseur légitime mais compromis recevrait sinon <code>DATABASE_URL</code>.</td></tr><tr><td><strong>Suivre les redirections</strong></td><td>Un 307 conserve le corps : le secret partirait vers l&#39;adresse désignée par la redirection, sans que la liste d&#39;hôtes ait été consultée.</td></tr><tr><td><strong><code>PyJWKClient</code> de PyJWT</strong></td><td>Synchrone, et passe par <code>urllib</code> sans les bornes de délai, de taille et de redirection de l&#39;échangeur.</td></tr><tr><td><strong>Mettre en cache découverte et JWKS</strong></td><td>Contraire au parti de l&#39;ADR-0016 (pas de cache sans mesure de charge) ; pour un événement rare (une connexion FranceConnect), un cache ajoute une durée de vie à choisir, une invalidation à la rotation des clés et un état à partager entre répliques.</td></tr><tr><td><strong>Accepter HS256</strong></td><td>Une signature par secret partagé est vérifiable par quiconque détient le secret, dont ce serveur : elle ne prouve pas l&#39;origine. FranceConnect v2 signe en RS256/ES256 ; v1, qui signait en HS256, est retiré.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>FranceConnect (et tout fournisseur OpenID Connect conforme) fonctionne sans une ligne de code chez l&#39;exploitant : un réglage d&#39;instance, une variable d&#39;environnement, un formulaire.</li><li>Une installation neuve n&#39;appelle toujours <strong>personne</strong> : sans <code>OIDC_ALLOWED_ISSUER_HOSTS</code>, le comportement est exactement l&#39;ancien (503).</li><li>Le secret client ne transite par aucune colonne, aucune réponse, aucun journal ; il ne part que vers un hôte déclaré par l&#39;instance, jamais par une redirection.</li><li>La grammaire des listes d&#39;hôtes est commune au socle IA et à l&#39;OIDC : un seul analyseur décide de ce qu&#39;est un hôte.</li><li>Un plugin peut toujours brancher un échangeur spécifique (authentification par clé privée, fournisseur non conforme) sans rien retirer au défaut.</li></ul><p><strong>Négatives, et il y en a</strong></p><ul><li><strong>Une nouvelle dépendance de production</strong> : <code>PyJWT[crypto]</code>, donc <code>cryptography</code>. Elle publie des roues musllinux, l&#39;image Alpine (ADR-0007) n&#39;a rien à compiler — à surveiller à chaque montée de version de Python.</li><li><strong>Quatre appels réseau par connexion</strong> (découverte, jeton, JWKS, userinfo), faute de cache. Assumé : quelques centaines de millisecondes sur un événement rare.</li><li><strong>La recette n&#39;a exercé qu&#39;un fournisseur simulé</strong> (<code>httpx.MockTransport</code>, clés générées). La conformité à l&#39;intégration FranceConnect réelle reste à éprouver.</li><li><strong>Le niveau de garantie n&#39;est pas contrôlé</strong> : <code>acr_values</code> est demandé à l&#39;autorisation, mais la revendication <code>acr</code> du jeton rendu n&#39;est confrontée à rien — ni dans l&#39;échangeur, ni dans <code>validate_id_token_claims</code>. Un fournisseur qui rendrait un niveau inférieur à celui demandé serait accepté.</li><li><strong>Pas de déconnexion fédérée</strong> : fermer la session du site ne ferme pas celle de FranceConnect (<code>end_session_endpoint</code> n&#39;est pas appelé).</li><li><strong>Les littéraux IPv6 restent hors grammaire</strong> des listes d&#39;hôtes, comme pour le socle IA.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Échangeur standard, registre à échangeur par défaut, <code>client_secret_env</code> à l&#39;écriture et à l&#39;usage, <code>OIDC_ALLOWED_ISSUER_HOSTS</code> vérifié au démarrage, ligne <code>oidc_injoignable</code>, champ de l&#39;écran Extranet › Politique — <code>apps/api/app/end_users/oidc_exchanger.py</code>, <code>apps/api/app/core/outbound_hosts.py</code>, recette <code>apps/api/tests/test_oidc_exchanger.py</code>.</li><li>[ ] Éprouver l&#39;échangeur contre l&#39;intégration FranceConnect réelle (<code>fcp-low.integ01.dev-franceconnect.fr</code>) : la recette n&#39;a exercé qu&#39;un fournisseur simulé.</li><li>[x] Déconnexion fédérée : appeler <code>end_session_endpoint</code> (avec <code>id_token_hint</code>) à la fermeture d&#39;une session ouverte par FranceConnect — attendue par FranceConnect avant une mise en production. <strong>Fait le 30/09/2026</strong> — <code>POST /logout</code> rend <code>federated_logout_url</code> (<code>end_session_endpoint</code> avec <code>id_token_hint</code>, <code>state</code> et <code>post_logout_redirect_uri</code> déclarée et autorisée) que le front fait suivre au navigateur ; le jeton d&#39;identité est gardé avec la session seulement si le fournisseur annonce une adresse de déconnexion sur un hôte déclaré, effacé à la fermeture et par la purge des sessions échues, jamais journalisé (migration <code>0046_deconnexion_federee.py</code>). Preuves : <code>tests/test_oidc_exchanger.py</code> (<code>test_la_deconnexion_d_une_session_oidc_rend_l_adresse_federee</code>, <code>test_deconnexion_hote_retire_ou_retour_refuse</code>, <code>test_sans_end_session_endpoint_rien_n_est_garde</code>, <code>test_federated_logout_url_reverifie_l_hote_au_moment_de_la_deconnexion</code>).</li><li>[x] Contrôler la revendication <code>acr</code> rendue contre <code>acr_values</code> demandé (aucun contrôle aujourd&#39;hui, vérifié dans <code>validate_id_token_claims</code> et dans l&#39;échangeur). <strong>Fait le 30/09/2026</strong> — <code>check_acr</code> (<code>app/end_users/oidc.py</code>) : un niveau inférieur au plus bas demandé (échelle <code>eidas1</code> &lt; <code>eidas2</code> &lt; <code>eidas3</code>), absent, ou hors échelle et différent des valeurs demandées refuse la connexion, journalisée <code>oidc_acr_refuse</code> ; sans <code>acr_values</code>, rien n&#39;est exigé. Preuves : <code>test_check_acr_accepte</code>, <code>test_check_acr_refuse</code>, <code>test_sans_acr_values_aucun_niveau_n_est_exige</code> (<code>tests/test_oidc_exchanger.py</code>).</li></ul>',33)])])}const h=n(a,[["render",c]]);export{g as __pageData,h as default};
